import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o}from"./chunks/ON.DXVlsWbj.js";import{_ as a,a as l,b as r}from"./chunks/M-S-SW3e.XAlFcJrn.js";import{_ as t,o as s,c as n,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const x=JSON.parse('{"title":"Pebble","description":"","frontmatter":{"source_hash":"d9a8e52f95","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/smartwatch/pebble.md","filePath":"it/smartwatch/pebble.md"}'),b={name:"it/smartwatch/pebble.md"};function d(c,e,m,_,u,h){return s(),n("div",null,[...e[0]||(e[0]=[p('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Caratteristiche Collegamenti Smart Watch<br>   Integrazione Pebble</p></div><p>xDrip supporta sia gli orologi Pebble originali (fuori produzione dal 2016) sia i nuovi modelli Pebble rilanciati nel 2025 (Pebble 2 Duo, Pebble Time 2).</p><p>Dopo aver associato il Pebble al telefono, puoi attivarlo in xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Integrazione Pebble Watch <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><p>xDrip installerà poi da solo il quadrante (non serve scaricarlo).</p><img src="'+a+'" style="zoom:75%;"><p>Ti proporrà anche di installare l&#39;app del pulsante di sospensione; se l&#39;hai saltata puoi farlo più tardi con Istalla Pebble Apps in fondo.</p><img src="'+l+'" style="zoom:75%;"><p>Puoi selezionare diversi quadranti.</p><div class="admonition xdripitem"><p class="admonition-title">Scegli Pebble Watchface</p></div><img src="'+r+'" style="zoom:75%;"><h2 id="new-pebble-models-2025-onwards" tabindex="-1">Nuovi modelli Pebble (dal 2025) <a class="header-anchor" href="#new-pebble-models-2025-onwards" aria-label="Permalink to &quot;Nuovi modelli Pebble (dal 2025) {#new-pebble-models-2025-onwards}&quot;">​</a></h2><p>Seleziona il quadrante Pebble Trend Clay Version (All Models) (<a href="https://github.com/jstevensog/xDrip-Pebble-E" target="_blank" rel="noreferrer">xDrip-Pebble-E</a>). Funziona su tutti i modelli Pebble, vecchi e nuovi, con tutti i colori sugli orologi a colori, compreso il nuovo Pebble Time 2.</p><h2 id="legacy-pebble-models" tabindex="-1">Modelli Pebble storici <a class="header-anchor" href="#legacy-pebble-models" aria-label="Permalink to &quot;Modelli Pebble storici {#legacy-pebble-models}&quot;">​</a></h2><p>Con le versioni di Android recenti, usare un vecchio orologio Pebble è <a href="https://www.reddit.com/r/pebble/comments/1776bbx/installing_pebble_apk_on_fresh_android_14_setup/" target="_blank" rel="noreferrer">complicato</a>. Usa le risorse di <a href="https://rebble.io/" target="_blank" rel="noreferrer">Rebble</a>.</p><p>I quadranti Standard, Color Trend e Pebble Classic Trend sono stati creati per i modelli Pebble originali. Anche il quadrante Pebble Trend Clay Version (All Models) funziona sui modelli storici.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.08.08" target="_blank" rel="noreferrer"><em>Ultima modifica 8/8/2026</em></a></p>',18)])])}const w=t(b,[["render",d]]);export{x as __pageData,w as default};
